<script setup lang="ts">import{onMounted,ref}from'vue';import{FolderKanban,Package,Workflow,Activity,AlertTriangle,ArrowUpRight}from'lucide-vue-next';import{api}from'../api';import StatCard from'../components/StatCard.vue';import StatusBadge from'../components/StatusBadge.vue';import EmptyState from'../components/EmptyState.vue';const data=ref<any>(),loading=ref(true);onMounted(async()=>{data.value=await api('/api/dashboard');loading.value=false});function progress(r:any){return r.node_count?Math.round(r.completed_nodes/r.node_count*100):0}</script>
<template><div class="page-heading"><div><span class="eyebrow">工作空间</span><h1>概览</h1><p>项目、产物与部署工作流的实时摘要。</p></div><router-link to="/projects" class="btn"><FolderKanban/>查看项目</router-link></div><div v-if="loading" class="stats-grid"><div v-for="n in 5" :key="n" class="card skeleton stat-card"></div></div><template v-else><div v-if="data.stats.failed" class="notice notice-danger"><AlertTriangle/><span>最近 7 天有 <b>{{data.stats.failed}}</b> 个失败运行需要关注。</span><router-link to="/runs">查看运行</router-link></div><section class="stats-grid"><StatCard label="项目" :value="data.stats.projects"><template #icon><FolderKanban/></template></StatCard><StatCard label="发布版本" :value="data.stats.releases"><template #icon><Package/></template></StatCard><StatCard label="工作流" :value="data.stats.workflows"><template #icon><Workflow/></template></StatCard><StatCard label="运行中" :value="data.stats.running"><template #icon><Activity/></template></StatCard><StatCard label="最近失败" :value="data.stats.failed"><template #icon><AlertTriangle/></template></StatCard></section><div class="content-grid"><section><div class="section-head"><div><h2>最近项目</h2><p>活跃项目及其交付概况</p></div><router-link to="/projects">全部项目</router-link></div><div class="project-grid"><router-link v-for="p in data.projects.slice(0,6)" :key="p.id" :to="`/projects/${p.id}`" class="card project-card"><div class="card-icon"><FolderKanban/></div><div class="grow"><h3>{{p.name}}</h3><p>{{p.latest_version||'暂无发布'}}</p><div class="mini-stats"><span>{{p.release_count}} 个版本</span><span>{{p.workflow_count}} 条工作流</span></div></div><ArrowUpRight class="arrow"/></router-link><EmptyState v-if="!data.projects.length" title="还没有项目" text="创建第一个项目开始接收 CI 产物。"/></div></section><section><div class="section-head"><div><h2>最近运行</h2><p>最新工作流执行状态</p></div><router-link to="/runs">全部运行</router-link></div><div class="card run-list"><div v-for="r in data.runs" :key="r.id" class="run-row"><div class="run-main"><b>{{r.workflow_name||'已删除的工作流'}}</b><span>{{r.project_name}} · {{r.version}}</span></div><div class="progress"><i :style="{width:`${progress(r)}%`}"></i></div><StatusBadge :status="r.status"/></div><EmptyState v-if="!data.runs.length" title="暂无运行记录"/></div></section></div></template></template>
